update ticket
set status = 'USED',
    verified_at = #{verifiedAt},
    updated_at = CURRENT_TIMESTAMP
where id = #{ticketId}
  and status = 'VALID'
  and valid_from <= #{verifiedAt}
  and valid_until > #{verifiedAt}
